window.NORWOOD_TRIVIA_QUESTIONS = [
{q:"Before Norwood became an independent town, what was the area commonly called?",a:["South Dedham","East Walpole","West Roxbury","North Canton"],c:0,cat:"History",fact:"Norwood was known as South Dedham before incorporation as its own town in 1872.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"In what year was Norwood incorporated as an independent Massachusetts town?",a:["1776","1822","1872","1928"],c:2,cat:"History",fact:"The Commonwealth officially recognized the new Town of Norwood on February 23, 1872.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"Who is pictured on Norwood's town seal?",a:["F. Holland Day","Aaron Guild","George F. Willett","Frank G. Allen"],c:1,cat:"Symbols",fact:"Aaron Guild and his oxen are featured on the Norwood town seal.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"What was the name of the southern Norwood settlement that developed around mills and industry?",a:["Tiot","Endicott","Westover","Morrill"],c:0,cat:"Places",fact:"South Norwood was historically associated with the name TIOT, a name that still appears in local history.",src:"https://norwoodhistoricalsociety.org/growth-and-development-of-the-south-norwood/"},
{q:"Near which present-day institution did South Dedham erect its first meetinghouse in 1736?",a:["Norwood Hospital","Morrill Memorial Library","Norwood High School","Norwood Memorial Airport"],c:1,cat:"History",fact:"The 1736 meetinghouse stood near the site of today's Morrill Memorial Library.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"When was South Dedham's first school built?",a:["1697","1740","1804","1872"],c:1,cat:"Schools",fact:"South Dedham built its first school in 1740 near the site of today's Callahan School.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"At first, who was allowed to attend South Dedham's early school?",a:["Only girls","Only boys","Only children over 12","Only mill workers' children"],c:1,cat:"Schools",fact:"The early school initially admitted boys only; girls were allowed to attend four years after the first schoolmaster was hired in 1754.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which Norwood photographer and publisher became an important figure in the Pictorialist movement?",a:["F. Holland Day","George H. Morrill","Walter Tilton","Cornelius Callahan"],c:0,cat:"People",fact:"F. Holland Day was an internationally significant photographer and publisher; his Norwood home is associated with the Historical Society.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which toy creator with a Norwood connection created My Little Pony?",a:["Bonnie Zacherle","Emily Curtis Fisher","Agnes Curtin","Marguerite Krupp"],c:0,cat:"People",fact:"Bonnie Zacherle, associated with Norwood, is the creator of My Little Pony.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which Norwood resident served as Governor of Massachusetts from 1929 to 1931?",a:["Frank G. Allen","George F. Willett","Calvin Coolidge","Henry O. Peabody"],c:0,cat:"People",fact:"Frank G. Allen, a Norwood resident, served as governor from 1929 to 1931.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which Norwood industrialist championed a 'Model Town' vision and helped shape the modern Town Square?",a:["George F. Willett","F. Holland Day","Aaron Guild","Ray Martin"],c:0,cat:"People",fact:"George F. Willett played a central role in planning Norwood's civic center and Town Square.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"What did George F. Willett do when the town would not fund widening Washington Street?",a:["Abandoned the plan","Paid for it himself","Moved the street","Built a trolley instead"],c:1,cat:"History",fact:"Historical accounts say Willett personally put up the money when the town would not appropriate funds to widen Washington Street.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"What occupied the spot on the Town Common before today's gazebo?",a:["A fountain","A large pine tree","A bandstand","A war memorial"],c:1,cat:"Places",fact:"The original Town Square had a large pine tree where the gazebo now stands.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"In what year was the Walter Dempsey Memorial Gazebo erected?",a:["1928","1954","1972","1993"],c:3,cat:"Places",fact:"The Walter Dempsey Memorial Gazebo was erected in 1993.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"On what date was Norwood's Memorial Municipal Building dedicated?",a:["July 4, 1872","November 11, 1928","January 1, 1931","May 8, 1945"],c:1,cat:"Architecture",fact:"The Memorial Municipal Building was dedicated on Sunday, November 11, 1928.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What musical feature of Norwood's Municipal Building began a continuing town tradition?",a:["A pipe organ","The Tilton Carillon","A steam whistle","A rooftop orchestra"],c:1,cat:"Architecture",fact:"The bells of the Tilton Carillon rang at the Municipal Building's dedication and became a continuing tradition.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Norwood adopted which form of professional municipal administration unusually early for New England?",a:["County executive","Town manager","Strong mayor","Ward council"],c:1,cat:"Government",fact:"By 1918, contemporary reporting highlighted Norwood for having adopted a town-manager form of government.",src:"https://norwoodhistoricalsociety.org/getting-ahead-of-the-future-this-day-in-norwood-history-january-27-1918/"},
{q:"Which Norwood body was established at Special Town Meeting on April 14, 1975?",a:["Historical Commission","Airport Commission","School Committee","Planning Board"],c:0,cat:"Government",fact:"The Norwood Historical Commission was established at Special Town Meeting on April 14, 1975.",src:"https://www.norwoodlibrary.org/wp-content/uploads/2023/06/2021_Norwood_Annual_Town_Report.pdf"},
{q:"Which of these movies is listed by Norwood on Film as having been shot in Norwood?",a:["Ted","Jaws","Good Will Hunting","Knives Out"],c:0,cat:"On Screen",fact:"Norwood on Film lists Ted among productions shot in town.",src:"https://www.norwoodonfilm.com/"},
{q:"Which 2016 supernatural comedy is listed as having filmed in Norwood?",a:["Ghostbusters","Central Intelligence","The Nice Guys","Office Christmas Party"],c:0,cat:"On Screen",fact:"Norwood on Film lists the 2016 Ghostbusters production among titles shot in Norwood.",src:"https://www.norwoodonfilm.com/"},
{q:"Which Robert Downey Jr. film is listed among productions shot in Norwood?",a:["The Judge","Iron Man 3","Due Date","Zodiac"],c:0,cat:"On Screen",fact:"The Judge is included on Norwood on Film's list of productions shot in town.",src:"https://www.norwoodonfilm.com/"},
{q:"Which romance title is listed by Norwood on Film as having shot in town?",a:["About Fate","The Holiday","27 Dresses","The Proposal"],c:0,cat:"On Screen",fact:"About Fate is among the productions listed as shot in Norwood.",src:"https://www.norwoodonfilm.com/"},
{q:"Which made-for-TV holiday title is associated with filming in Norwood?",a:["A Showstopping Christmas","Christmas in Connecticut","A Biltmore Christmas","The Christmas Train"],c:0,cat:"On Screen",fact:"Norwood on Film lists A Showstopping Christmas, also known as A Playful Romance.",src:"https://www.norwoodonfilm.com/"},
{q:"How many commuter rail stations does Norwood have?",a:["One","Two","Three","Four"],c:2,cat:"Around Town",fact:"Norwood has three commuter rail stations: Windsor Gardens, Norwood Central and Norwood Depot.",src:"https://www.norwoodonfilm.com/"},
{q:"Which of these is NOT one of Norwood's three commuter rail stations?",a:["Norwood Central","Norwood Depot","Windsor Gardens","University Avenue"],c:3,cat:"Around Town",fact:"University Avenue is nearby in Westwood; Norwood's three stations are Windsor Gardens, Norwood Central and Norwood Depot.",src:"https://www.norwoodonfilm.com/"},
{q:"Which Norwood estate hosted guests including presidents, artists and composer Sergei Rachmaninoff?",a:["Oak View","Day House","Tiot Tavern","Village Hall"],c:0,cat:"Places",fact:"Oak View was home to the Winslow and Allen families and hosted an extraordinary range of prominent guests.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which U.S. presidents are documented as guests at Oak View?",a:["Taft and Coolidge","Lincoln and Grant","Kennedy and Johnson","Roosevelt and Truman"],c:0,cat:"People",fact:"The Historical Society identifies William Howard Taft and Calvin Coolidge among Oak View's notable guests.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which famous American painter is listed among Oak View's notable guests?",a:["John Singer Sargent","Edward Hopper","Norman Rockwell","Winslow Homer"],c:0,cat:"People",fact:"John Singer Sargent is among the notable visitors documented at Oak View.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which philosopher is listed among Oak View's notable guests?",a:["William James","John Dewey","Henry David Thoreau","Ralph Waldo Emerson"],c:0,cat:"People",fact:"William James is among the prominent guests associated with Oak View.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which Russian composer visited Oak View?",a:["Sergei Rachmaninoff","Igor Stravinsky","Pyotr Tchaikovsky","Dmitri Shostakovich"],c:0,cat:"People",fact:"Sergei Rachmaninoff is listed among Oak View's notable guests.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Willett Pond was originally created in part to provide what for the Winslow tanneries?",a:["Controlled water power","Drinking water only","Ice for shipping","A rail connection"],c:0,cat:"Nature",fact:"Willett Pond was man-made to provide controlled water power for the Winslow tanneries, while also becoming a recreation and beauty spot.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which company built a Norwood plant supporting the World War II effort?",a:["Bendix Aviation","Ford Motor Company","General Electric","Bethlehem Steel"],c:0,cat:"History",fact:"Bendix Aviation built a plant in Norwood that provided equipment for the war effort.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"During the 1930s, how many New Haven Railroad stations did Norwood have?",a:["One","Two","Three","Five"],c:2,cat:"History",fact:"A historical account describes three New Haven Railroad stations in Norwood during the 1930s.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"In the 1930s, Washington Street was also served by how many electric railways?",a:["One","Two","Three","Six"],c:2,cat:"History",fact:"Historical accounts describe three electric railways whose tracks ran through the Washington Street business district.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What major Norwood publishing business was founded in 1897?",a:["Plimpton Press","Morrill Ink","Norwood Record","South Dedham Gazette"],c:0,cat:"Industry",fact:"Plimpton Press was founded in 1897 and later became one of Norwood's major employers.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which Norwood businessman is credited in local history as the first person in Boston to drive a gasoline automobile?",a:["George H. Morrill","George F. Willett","Frank G. Allen","Francis O. Winslow"],c:0,cat:"People",fact:"The Historical Society credits George H. Morrill, owner of Morrill Ink Co., as the first person in Boston to drive a gasoline automobile.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which inventor associated with Norwood developed the Peabody rifle?",a:["Henry Oliver Peabody","Walter Tilton","Lyman Smith","Manasseh Cutler"],c:0,cat:"People",fact:"Henry Oliver Peabody is remembered for the Peabody rifle and Norwood's early industrial innovation.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"What industry did Lyman Smith establish in South Norwood in 1776?",a:["Sheepskin tannery","Printing press","Aircraft factory","Automobile dealership"],c:0,cat:"Industry",fact:"The Historical Society identifies Lyman Smith with a pioneering sheepskin tannery in South Norwood dating to 1776.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which Norwood athlete played for the Boston Braves and faced Babe Ruth?",a:["Ray Martin","Ernie Boch","James Pendergast","Nicholas Abdallah"],c:0,cat:"Sports",fact:"Norwood pitching star Ray Martin played for the Boston Braves and faced Babe Ruth.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"The Balch School was named for whom?",a:["Rev. Thomas Balch","Benjamin Balch","Mary Balch","Frederick Balch"],c:0,cat:"Schools",fact:"The Balch School was named for Rev. Thomas Balch, pastor of South Dedham's early Congregational Church.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Who built what local history describes as the first house in what became Norwood?",a:["Ezra Morse","Aaron Guild","Thomas Balch","George Willett"],c:0,cat:"History",fact:"Local historical accounts identify Ezra Morse's 1678 saltbox dwelling on Morse Hill as the first house in Norwood.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"In what year did South Dedham begin holding services in private homes while seeking its own parish?",a:["1675","1722","1776","1820"],c:1,cat:"History",fact:"South Dedham parishioners began holding services in private homes in 1722 during their push for a separate parish.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"When did the General Court incorporate the area as the South Parish of Dedham?",a:["1730","1772","1830","1872"],c:0,cat:"History",fact:"The South Parish of Dedham was incorporated on October 18, 1730.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"Which future nationally prominent figure taught school in South Dedham in 1765–66?",a:["Manasseh Cutler","John Adams","Paul Revere","Horace Mann"],c:0,cat:"People",fact:"Manasseh Cutler, Yale 1765, taught the local district school from December 1765 to April 1766.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-february-12-1935-tales-of-tyot-colonial-school-masters-of-tiot/"},
{q:"Which immigrant community was the first identified in local history as settling South Norwood in the 1890s?",a:["Lithuanians","Greeks","Portuguese","Poles"],c:0,cat:"Community",fact:"A Historical Society account identifies Lithuanians as the first immigrant group to settle South Norwood in the 1890s.",src:"https://norwoodhistoricalsociety.org/growth-and-development-of-the-south-norwood/"},
{q:"By 1915, approximately how many Lithuanians lived in South Norwood according to local history?",a:["About 50","About 200","More than 500","More than 5,000"],c:2,cat:"Community",fact:"Local history reports that chain migration helped grow South Norwood's Lithuanian community to more than 500 by 1915.",src:"https://norwoodhistoricalsociety.org/growth-and-development-of-the-south-norwood/"},
{q:"Which site became the Norwood Historical Society's permanent home in 1934?",a:["Day House","Oak View","Town Hall","Tiot Tavern"],c:0,cat:"Places",fact:"The Norwood Historical Society acquired the Day House as its permanent home in 1934.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What transportation facility opened during Frank G. Allen's term as Massachusetts governor?",a:["Norwood Municipal Airport","Route 128 station","Norwood Central","Windsor Gardens"],c:0,cat:"Around Town",fact:"Norwood Municipal Airport opened during Frank G. Allen's 1929–31 governorship.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which street did George Willett's Town Center plan help reshape into Norwood's commercial core?",a:["Washington Street","Route 1","Nahatan Street","Dean Street"],c:0,cat:"Places",fact:"Willett's plan reshaped the Town Center around Washington Street, the Common and surrounding civic/commercial blocks.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"What was the land that became the Town Common area once known as?",a:["The Hook","The Neck","The Flats","The Green Mile"],c:0,cat:"Places",fact:"George Willett purchased land known as The Hook as part of his plan for a town common and commercial district.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which of these is listed as a production shot in Norwood?",a:["Labor Day","Mystic River","The Departed","CODA"],c:0,cat:"On Screen",fact:"Labor Day appears on Norwood on Film's list of productions shot in town.",src:"https://www.norwoodonfilm.com/"},
{q:"Which unreleased/science-fiction production is listed by Norwood on Film among projects shot in town?",a:["The Mothership","Don't Look Up","Free Guy","Finch"],c:0,cat:"On Screen",fact:"The Mothership is included in Norwood on Film's production list.",src:"https://www.norwoodonfilm.com/"},
{q:"Norwood lies roughly between which two major New England cities, according to the town's film-location site?",a:["Boston and Providence","Boston and Worcester","Providence and Hartford","Worcester and Springfield"],c:0,cat:"Geography",fact:"Norwood on Film promotes the town as centrally located between Boston and Providence.",src:"https://www.norwoodonfilm.com/"},
{q:"What river is closely associated with Norwood's early settlement and industrial history?",a:["Neponset River","Charles River","Merrimack River","Blackstone River"],c:0,cat:"Nature",fact:"The Neponset River and its tributaries played important roles in settlement, mills and South Norwood industry.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which Norwood school site is near the location of South Dedham's first 1740 school?",a:["Callahan Elementary School","Norwood High School","Balch School","Coakley Middle School"],c:0,cat:"Schools",fact:"The first school was built near the site of today's Cornelius Callahan Elementary School.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"How many years before incorporation did Norwood's first Balch Schoolhouse open in 1867?",a:["5 years","15 years","25 years","50 years"],c:0,cat:"Schools",fact:"The first Balch Schoolhouse opened in 1867, five years before Norwood's 1872 incorporation.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which Supreme Court justice is listed among Oak View's distinguished visitors?",a:["Oliver Wendell Holmes","Louis Brandeis","Earl Warren","Thurgood Marshall"],c:0,cat:"People",fact:"Justice Oliver Wendell Holmes is among the prominent guests documented at Oak View.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which Japanese diplomat is listed among Oak View's notable visitors?",a:["Viscount Kentaro Kaneko","Chiune Sugihara","Katsu Kaishu","Inazo Nitobe"],c:0,cat:"People",fact:"Viscount Kentaro Kaneko is included among Oak View's notable guests.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which Irish tenor visited Oak View?",a:["John McCormack","Bono","Ronan Tynan","Luke Kelly"],c:0,cat:"People",fact:"Irish tenor John McCormack is listed among Oak View's distinguished visitors.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"What type of business was the Winslow family especially associated with in Norwood?",a:["Tanneries","Shipbuilding","Textiles","Banking"],c:0,cat:"Industry",fact:"The Winslow family was associated with the nationally prominent Winslow Brothers Tannery.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"What did Norwood's World War II-era Honor Roll commemorate?",a:["Local men and women who served","Town managers","Factory owners","High-school athletes"],c:0,cat:"History",fact:"The town's Honor Roll commemorated Norwood residents who served during World War II.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which source lets visitors search Norwood historical newspapers beginning in 1887?",a:["Morrill Memorial Library","Norwood Airport","MBTA","Recreation Department"],c:0,cat:"Archives",fact:"Morrill Memorial Library provides a digital archive of local newspapers beginning with the Advertiser and Review in 1887.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Norwood's digitized Annual Town Reports available through the library begin in what year?",a:["1776","1873","1928","1950"],c:1,cat:"Archives",fact:"The library's Norwood history archive links Town Annual Reports beginning in 1873.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which local newspaper in the library archive ran from 1937 to 1950?",a:["Norwood Free Press","Norwood Advertiser","Norfolk County Press","Advertiser and Review"],c:0,cat:"Archives",fact:"The Norwood Free Press is archived for 1937–1950.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which local newspaper archive covers 1894–1905?",a:["Norwood Advertiser","Norwood Free Press","Norfolk County Free Press","Norwood Record"],c:0,cat:"Archives",fact:"The Morrill Memorial Library archive lists the Norwood Advertiser for 1894–1905.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which town institution preserves Norwood High School TIOT yearbooks online?",a:["Morrill Memorial Library","Town Clerk only","Historical Commission only","Norwood Community Media"],c:0,cat:"Archives",fact:"The library's digital history resources include Norwood High School TIOT yearbooks.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which movie title is NOT on Norwood on Film's current 'Shot in Norwood' list?",a:["The Departed","Ted","The Judge","About Fate"],c:0,cat:"On Screen",fact:"Ted, The Judge and About Fate are listed; The Departed is not on the site's current Shot in Norwood list.",src:"https://www.norwoodonfilm.com/"},
{q:"Which civic space did George F. Willett specifically advocate for in 1916?",a:["Town Square","Municipal airport","Highway interchange","Shopping mall"],c:0,cat:"History",fact:"A 1947 historical sketch recalls Willett speaking in 1916 about the need for a Town Square.",src:"https://norwoodhistoricalsociety.org/1947-historical-sketch-the-norwood-business-association/"},
{q:"What was one original purpose of Willett Pond besides recreation and beauty?",a:["Powering industry","Salt production","Flooding cranberry bogs","Supplying steam locomotives"],c:0,cat:"Nature",fact:"Willett Pond was created to help provide controlled water power for industry.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which current Norwood landmark was planned as part of a larger civic center vision?",a:["Town Common","Route 1 Automile","Airport runway","University Station"],c:0,cat:"Architecture",fact:"The Town Common and surrounding civic center grew from George Willett's ambitious Town Center planning.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"What was the profession of F. Holland Day in addition to publishing?",a:["Photographer","Architect","Composer","Physician"],c:0,cat:"People",fact:"F. Holland Day was a pioneering photographer as well as a publisher.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which Norwood figure's home is described as a Gothic Revival masterpiece?",a:["F. Holland Day","Frank G. Allen","Ray Martin","George H. Morrill"],c:0,cat:"Architecture",fact:"The Historical Society describes F. Holland Day's home as a Gothic Revival masterpiece.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"What was Frank G. Allen's connection to Oak View?",a:["He lived there","He designed it","He demolished it","He used it as Town Hall"],c:0,cat:"Places",fact:"Governor Frank G. Allen resided at Oak View during the early 20th century.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which of these descriptions best fits Oak View's historical role?",a:["A private estate that became a hub of political and cultural life","Norwood's first railroad depot","A colonial schoolhouse","A World War II aircraft plant"],c:0,cat:"Places",fact:"Under the Winslow and Allen families, Oak View hosted prominent political and cultural figures.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which war brought colonial troops through the area near present-day Pleasant Street in 1675?",a:["King Philip's War","French and Indian War","Revolutionary War","War of 1812"],c:0,cat:"History",fact:"Local history describes colonial troops passing through the area during the opening of King Philip's War in 1675.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"What unusual astronomical event occurred as troops neared King's Bridge in June 1675?",a:["A lunar eclipse","A solar eclipse","A meteor shower","A comet"],c:0,cat:"History",fact:"A lunar eclipse occurred as colonial troops neared King's Bridge; historical accounts say they interpreted it as an omen.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"Which road crossing is associated with the historic King's Bridge location?",a:["Pleasant Street over the Neponset River","Washington Street over Route 1","Nahatan Street over the railroad","Dean Street over Hawes Brook"],c:0,cat:"Places",fact:"Local history places King's Bridge where present-day Pleasant Street crosses the Neponset River.",src:"https://norwoodhistoricalsociety.org/happy-birthday-norwood-massachusetts/"},
{q:"Which production title has the alternate name 'A Playful Romance'?",a:["A Showstopping Christmas","About Fate","Labor Day","Blunt"],c:0,cat:"On Screen",fact:"Norwood on Film identifies A Showstopping Christmas with the alternate title A Playful Romance.",src:"https://www.norwoodonfilm.com/"},
{q:"What kind of attraction does Norwood on Film emphasize to location scouts?",a:["A mix from country to urban and historic to modern","Only industrial sites","Only suburban homes","Only railroad property"],c:0,cat:"On Screen",fact:"The town's film-location site promotes Norwood's range of country, urban, quaint, modern and industrial location types.",src:"https://www.norwoodonfilm.com/"},
{q:"Which major highways does Norwood on Film cite as making the town accessible?",a:["Routes 95, 1 and nearby 90","Routes 2 and 3 only","I-91 and I-84","Route 6 only"],c:0,cat:"Geography",fact:"Norwood on Film highlights Route 95 and Route 1, with Route 90 nearby.",src:"https://www.norwoodonfilm.com/"},
{q:"What type of facility is Norwood Memorial Airport?",a:["A municipal airport","A military-only airfield","A heliport only","A closed historic runway"],c:0,cat:"Around Town",fact:"Norwood Memorial Airport is an active local airport serving local, regional and national needs.",src:"https://www.norwoodonfilm.com/"},
{q:"Which person is the namesake of Norwood's local-history Pendergast archives?",a:["James Pendergast","Frank Allen","Aaron Guild","Walter Dempsey"],c:0,cat:"People",fact:"The Historical Society identifies James Pendergast as a central figure in town government and namesake of local-history archives.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which Norwood educator and civic leader is the namesake of Cleveland Elementary School?",a:["Frederick A. Cleveland","Grover Cleveland","Manasseh Cutler","Thomas Balch"],c:0,cat:"Schools",fact:"Frederick A. Cleveland is identified by the Historical Society as the namesake of Cleveland Elementary School.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which historic Norwood estate is at 289 Walpole Street?",a:["Oak View","Day House","Tiot Tavern","Village Hall"],c:0,cat:"Places",fact:"Oak View is located at 289 Walpole Street.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Who was known as 'Mr. Norwood' in the Historical Society's account of Oak View?",a:["Francis Olmsey Winslow","George F. Willett","Frank G. Allen","F. Holland Day"],c:0,cat:"People",fact:"Francis Olmsey Winslow is described as 'Mr. Norwood' for his broad involvement in business and civic life.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"The present Town Common was part of a plan that also mapped sites for what?",a:["Town Hall, theater and Washington Street blocks","An ocean port","A state capitol","A university campus"],c:0,cat:"Architecture",fact:"Willett's Town Center plan mapped sites for Town Hall, a theater and commercial blocks along Washington Street.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which street did Willett create by extending Market Street toward Cemetery Way?",a:["Central Street","Guild Street","Morse Street","Dean Street"],c:0,cat:"Places",fact:"The Historical Society's Town Square account says Willett extended the area and created Central Street.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Before the gazebo was built, what kind of feature gave the Town Square a natural focal point?",a:["A large pine tree","A pond","An elm arch","A rock outcrop"],c:0,cat:"Nature",fact:"A large pine tree once stood where the gazebo is now located.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"What was Norwood's population center historically known for in addition to industry?",a:["Trade and transportation","Whaling","Deep-sea fishing","Gold mining"],c:0,cat:"History",fact:"Historical accounts describe 1930s Norwood as retaining its character as a trade and transportation center.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What happened throughout Norwood when World War II ended?",a:["The town's bells rang in celebration","The airport closed","The Town Hall lights went dark","The railways stopped"],c:0,cat:"History",fact:"The Historical Society recounts that all the bells in town rang in celebration when the war ended.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which Norwood resource includes municipal records as well as newspapers and annual reports?",a:["Morrill Memorial Library's digital archive","Norwood on Film","MBTA schedules","Recreation registration"],c:0,cat:"Archives",fact:"Morrill Memorial Library's Norwood history portal brings together historical newspapers, annual reports and municipal records.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which historic database does Morrill Memorial Library point researchers to for Massachusetts historic properties?",a:["MACRIS","IMDb","MassGIS Trails","WorldCat only"],c:0,cat:"Archives",fact:"The library links to MACRIS, the Massachusetts Cultural Resource Information System.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"What does the 'TIOT' name still identify in the library's historical collections?",a:["Norwood High School yearbooks","Airport flight logs","Town tax bills","Commuter rail timetables"],c:0,cat:"Archives",fact:"The library provides access to Norwood High School TIOT yearbooks.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which Norwood historical figure worked to create a planned subdivision called Westover?",a:["George F. Willett","F. Holland Day","Henry Peabody","Ray Martin"],c:0,cat:"Places",fact:"A historical account credits George F. Willett with conceiving the town's first planned subdivision in Westover.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"What was one recreation use historically associated with Willett Pond?",a:["Boating","Downhill skiing","Ocean surfing","Horse racing"],c:0,cat:"Nature",fact:"Historical accounts describe Willett Pond as supporting boating and other recreation.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which of these prominent visitors to Oak View was a composer?",a:["Sergei Rachmaninoff","John Singer Sargent","William James","Oliver Wendell Holmes"],c:0,cat:"People",fact:"Rachmaninoff was a Russian composer; the other listed visitors were a painter, philosopher and jurist.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which of these Oak View visitors was a painter?",a:["John Singer Sargent","Sergei Rachmaninoff","William James","John McCormack"],c:0,cat:"People",fact:"John Singer Sargent was the celebrated painter among Oak View's documented guests.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which of these Oak View visitors was an Irish tenor?",a:["John McCormack","William James","Calvin Coolidge","Kentaro Kaneko"],c:0,cat:"People",fact:"John McCormack was a celebrated Irish tenor.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"What kind of mill did Ezra Morse operate in the area's early settlement period?",a:["Grist mill","Steel mill","Paper mill","Textile mill"],c:0,cat:"Industry",fact:"Ezra Morse operated a grist mill, an important part of the area's early settlement history.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Morse Hill takes its name from which early settler family?",a:["Morse","Willett","Winslow","Morrill"],c:0,cat:"Places",fact:"The hill associated with Ezra Morse's early dwelling became known as Morse Hill.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which title in Norwood's historic newspaper archive began in 1887?",a:["Advertiser and Review","Norwood Free Press","Norfolk County Press","Norwood Town News"],c:0,cat:"Archives",fact:"The Advertiser and Review is available in the library's archive beginning in 1887.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"What was one stated purpose of Norwood's Historical Commission?",a:["Preserving places and assets significant to Norwood history","Running commuter rail","Issuing restaurant licenses","Managing school athletics"],c:0,cat:"Government",fact:"The commission's stated purpose includes preservation and protection of buildings, places and assets significant to Norwood history.",src:"https://www.norwoodlibrary.org/wp-content/uploads/2023/06/2021_Norwood_Annual_Town_Report.pdf"},
{q:"Which of these titles appears on Norwood on Film's 'Shot in Norwood' list?",a:["Blunt","The Holdovers","Manchester by the Sea","Spotlight"],c:0,cat:"On Screen",fact:"Blunt is listed among projects shot in Norwood.",src:"https://www.norwoodonfilm.com/"},
{q:"Which title appears on Norwood on Film's list alongside Ted and The Judge?",a:["Thug","Oppenheimer","Air","CODA"],c:0,cat:"On Screen",fact:"Thug is one of the productions listed by Norwood on Film.",src:"https://www.norwoodonfilm.com/"},
{q:"Which landmark's carillon bells were a gift associated with Walter F. Tilton?",a:["Memorial Municipal Building","Morrill Memorial Library","Norwood High School","Day House"],c:0,cat:"Architecture",fact:"The Tilton Carillon is part of Norwood's Memorial Municipal Building.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What was Norwood's name immediately before incorporation?",a:["South Dedham","South Walpole","West Dedham","Tiot Township"],c:0,cat:"History",fact:"Norwood grew from the South Dedham parish/community before becoming independent in 1872.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which community split helped lead South Dedham to establish its own meetinghouse?",a:["West Dedham and South Dedham disagreed on a combined meetinghouse location","Canton annexed the town square","Walpole closed the parish","Boston moved the county seat"],c:0,cat:"History",fact:"West Dedham and South Dedham could not agree on the location of a combined meetinghouse, and South Dedham erected its own in 1736.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"What was a notable limitation of South Dedham's first school?",a:["Teachers had to travel from Dedham","It met only at night","It was on an island","It taught only Latin"],c:0,cat:"Schools",fact:"Teachers initially had to travel from Dedham each day, sessions were short, and only boys attended.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which historical figure married Mary Balch after teaching in South Dedham?",a:["Manasseh Cutler","Aaron Guild","Frank Allen","George Morrill"],c:0,cat:"People",fact:"Manasseh Cutler taught locally in 1765–66 and later married Mary Balch.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-february-12-1935-tales-of-tyot-colonial-school-masters-of-tiot/"},
{q:"Which historical feature was near the present-day Norwood Space Center/CertainTeed area?",a:["Ezra Morse's early mill","The first Town Hall","Oak View","The first airport terminal"],c:0,cat:"Places",fact:"Local history places Ezra Morse's mill roughly near present-day Morse Street/Water Street and the Norwood Space Center/CertainTeed area.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"What kind of community did George F. Willett hope Norwood could become?",a:["A 'Model Town'","A state capital","A seaport","A university town"],c:0,cat:"History",fact:"Willett's civic planning and philanthropy were associated with a 'Model Town' vision for Norwood.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which town landmark did Willett's planning place at the center of a new downtown?",a:["Town Common","Airport","High school stadium","Route 1 rotary"],c:0,cat:"Places",fact:"Willett laid out the Town Common as the center of a redesigned downtown.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which early Norwood industry was tied to animal hides?",a:["Tanning","Shipbuilding","Glassmaking","Coal mining"],c:0,cat:"Industry",fact:"Tanneries, including the Winslow enterprises, were major parts of Norwood's industrial history.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which famous toy brand has a creator connected to Norwood?",a:["My Little Pony","Barbie","LEGO","Hot Wheels"],c:0,cat:"People",fact:"Bonnie Zacherle, associated with Norwood, created My Little Pony.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which prominent Norwood resident's political career reached the Massachusetts governorship?",a:["Frank G. Allen","F. Holland Day","Henry Peabody","Walter Dempsey"],c:0,cat:"People",fact:"Frank G. Allen served as Governor of Massachusetts from 1929 to 1931.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What was Oak View closely associated with economically?",a:["The Winslow Brothers Tannery fortune","The Plimpton Press only","Railroad ownership","Shipbuilding"],c:0,cat:"Industry",fact:"Oak View was associated with Francis Olmsey Winslow, heir to the Winslow Brothers Tannery enterprise.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which of these is a historic Norwood mansion rather than a rail station?",a:["Oak View","Windsor Gardens","Norwood Depot","Norwood Central"],c:0,cat:"Places",fact:"Oak View is a historic estate on Walpole Street.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"What does Norwood's film-location program call its list of local productions?",a:["Shot in Norwood","Made on Route 1","Norwood Pictures","Hollywood South"],c:0,cat:"On Screen",fact:"The Norwood on Film site presents a 'Shot in Norwood' collection of productions.",src:"https://www.norwoodonfilm.com/"},
{q:"What kind of local history source dates back to 1873 in the library collection?",a:["Annual Town Reports","Television broadcasts","Airport logs","Highway maps"],c:0,cat:"Archives",fact:"Digitized Norwood Annual Town Reports are available from 1873 onward.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which organization is headquartered at the historic F. Holland Day House?",a:["Norwood Historical Society","Norwood Recreation","MBTA","Norwood Light"],c:0,cat:"Places",fact:"The F. Holland Day House serves as the headquarters/home of the Norwood Historical Society.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which part of Norwood saw a substantial Lithuanian community develop around mills, presses and factories?",a:["South Norwood","Westover only","Town Common","Airport district"],c:0,cat:"Community",fact:"South Norwood/TIOT developed a significant Lithuanian community around industrial employment.",src:"https://norwoodhistoricalsociety.org/growth-and-development-of-the-south-norwood/"},
{q:"Which of these best describes Norwood's historic economic mix?",a:["Manufacturing, printing, tanning and transportation","Whaling and cod fishing","Gold and silver mining","Cotton plantations"],c:0,cat:"Industry",fact:"Norwood's history includes major manufacturing, printing, tanning and transportation activity.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which public space is home to the Walter Dempsey Memorial Gazebo?",a:["Norwood Town Common","Willett Pond","Norwood Airport","Endean Park"],c:0,cat:"Places",fact:"The gazebo stands on Norwood's Town Common/Town Square.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which local figure financed significant civic improvements and reportedly spent about $1 million improving Norwood?",a:["George F. Willett","Aaron Guild","Ray Martin","Thomas Balch"],c:0,cat:"People",fact:"Historical accounts credit George F. Willett with extensive personal spending on Norwood civic improvements.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"What happened to George F. Willett's fortune and industries after a 1924 stock suit, according to a historical account?",a:["They were wiped out","They doubled","They moved to Canada","They became town property immediately"],c:0,cat:"History",fact:"A 1964 historical account says Willett's fortune and industries were wiped out in a 1924 stock suit.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which Norwood company was historically a major printing employer?",a:["Plimpton Press","Bendix Aviation","Winslow Brothers","Morrill Ink"],c:0,cat:"Industry",fact:"Plimpton Press, founded in 1897, became one of Norwood's major employers.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-march-29/"},
{q:"Which local industry was represented by George H. Morrill?",a:["Ink manufacturing","Aircraft engines","Tanning","Railroads"],c:0,cat:"Industry",fact:"George H. Morrill owned Morrill Ink Co., an important Norwood industrial enterprise.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which public institution is the best starting point on Norwood.ma's sources for digitized local newspapers?",a:["Morrill Memorial Library","Norwood on Film","Town Recreation","MBTA"],c:0,cat:"Archives",fact:"Morrill Memorial Library hosts the searchable historical newspaper archive.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"What is the oldest newspaper date currently listed in Morrill Memorial Library's Norwood archive?",a:["1887","1901","1937","1950"],c:0,cat:"Archives",fact:"The Advertiser and Review collection begins in 1887.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"Which archive title followed the Norwood Free Press beginning in 1950?",a:["Norfolk County Free Press","Norwood Advertiser","Advertiser and Review","Boston Record"],c:0,cat:"Archives",fact:"The library lists Norfolk County Free Press for 1950–1962 after the Norwood Free Press collection.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"What did Norwood's early 20th-century civic planners want Town Square to anchor?",a:["A redesigned downtown and civic center","An amusement park","A university","A seaport"],c:0,cat:"Architecture",fact:"The Town Square was conceived as the centerpiece of a planned civic and commercial center.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which of these is true about the Town Common gazebo?",a:["It dates to 1993","It was built in 1736","It predates the town","It was originally a train shelter"],c:0,cat:"Places",fact:"The Walter Dempsey Memorial Gazebo was erected in 1993.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"What did South Dedham gain in 1754?",a:["Its first schoolmaster","Its independence as Norwood","Its airport","Its town manager"],c:0,cat:"Schools",fact:"South Dedham hired its first schoolmaster in 1754.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Four years after hiring its first schoolmaster, what changed at the local school?",a:["Girls were allowed to attend","It became a college","It moved to Boston","It closed permanently"],c:0,cat:"Schools",fact:"Girls were allowed to attend four years after South Dedham hired its first schoolmaster.",src:"https://norwoodhistoricalsociety.org/a-brief-history-of-norwood-massachusetts/"},
{q:"Which historical Norwood building is tied to an internationally important photographer?",a:["F. Holland Day House","Memorial Municipal Building","Balch School","Plimpton Press"],c:0,cat:"Architecture",fact:"The F. Holland Day House is associated with the influential photographer and publisher.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"Which film-related advantage does Norwood promote besides varied locations?",a:["Access between Boston and Providence","Oceanfront beaches","Desert landscapes","Mountain ski resorts"],c:0,cat:"On Screen",fact:"Norwood's film-location site emphasizes its location between Boston and Providence and highway/transit access.",src:"https://www.norwoodonfilm.com/"},
{q:"Which production on Norwood on Film's list shares its title with a federal holiday?",a:["Labor Day","The Judge","Ted","Thug"],c:0,cat:"On Screen",fact:"Labor Day is listed among productions shot in Norwood.",src:"https://www.norwoodonfilm.com/"},
{q:"Which Norwood site combines historic architecture with a connection to a Massachusetts governor?",a:["Oak View","Windsor Gardens station","Norwood Depot","Airport hangar"],c:0,cat:"Architecture",fact:"Oak View was home to Governor Frank G. Allen and the Winslow family.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which town-history source describes Norwood as having 'upset New England traditions' with its planning and government?",a:["A 1918 Providence Journal account","A 1776 diary","A 1960 TV script","An MBTA report"],c:0,cat:"Government",fact:"A 1918 account reprinted by the Historical Society highlighted Norwood's town manager and civic planning as unusually forward-looking.",src:"https://norwoodhistoricalsociety.org/getting-ahead-of-the-future-this-day-in-norwood-history-january-27-1918/"},
{q:"What organization did George F. Willett help use to promote town welfare and civic improvement?",a:["Norwood Civic Association","MBTA","Massport","Norfolk County Fair Board"],c:0,cat:"Government",fact:"Historical accounts identify Willett as a driving force behind the Civic Association and its town-improvement mission.",src:"https://norwoodhistoricalsociety.org/getting-ahead-of-the-future-this-day-in-norwood-history-january-27-1918/"},
{q:"Which local history category would best fit the Tilton Carillon?",a:["Music and civic architecture","Baseball","Railroads","Film production"],c:0,cat:"Culture",fact:"The Tilton Carillon is both an architectural feature of Town Hall and a longstanding part of Norwood's civic soundscape.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which Norwood resource is specifically designed to attract movie and TV productions?",a:["Norwood on Film","Morrill Memorial Library","Norwood Light","Trails Committee"],c:0,cat:"On Screen",fact:"Norwood on Film promotes the town's locations and production advantages to filmmakers.",src:"https://www.norwoodonfilm.com/"},
{q:"Which local landmark was dedicated just before the Great Depression began?",a:["Memorial Municipal Building","Walter Dempsey Gazebo","Norwood High School's current building","Windsor Gardens station"],c:0,cat:"Architecture",fact:"The Municipal Building was dedicated in November 1928; the stock-market crash followed in 1929.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What was one use of the Day House after the Historical Society acquired it?",a:["Art classes","Airport control tower","Police station","Train ticket office"],c:0,cat:"Culture",fact:"Historical accounts note that art classes were held at the Day House after the Society acquired it.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which historical figure was both an educator and activist in Norwood's 'Wonderful Women' archives?",a:["Emily Curtis Fisher","Bonnie Zacherle","Phebe Willett","Mary Balch"],c:0,cat:"People",fact:"The Historical Society highlights Emily Curtis Fisher as an educator and activist in its Wonderful Women material.",src:"https://norwoodhistoricalsociety.org/innovators-and-icons-the-stories-behind-norwoods-most-famous-names/"},
{q:"What type of business made the Winslow family nationally prominent?",a:["Tannery","Movie studio","Airline","Newspaper chain"],c:0,cat:"Industry",fact:"The Winslow Brothers Tannery was a locally important enterprise with broader renown.",src:"https://norwoodhistoricalsociety.org/oakview-mansion/"},
{q:"Which local landmark's story connects George Willett, a pine tree and a 1993 gazebo?",a:["Town Square/Common","Willett Pond","Airport","Day House"],c:0,cat:"Places",fact:"All three are part of the history of Norwood's Town Square/Common.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"Which town-history archive includes a burial database and map for Old Parish Cemetery?",a:["Morrill Memorial Library's history resources","Norwood on Film","MBTA","Recreation Department"],c:0,cat:"Archives",fact:"The library's Norwood history page links an Old Parish Cemetery map and burial database.",src:"https://norwoodlibrary.org/digital-archive/"},
{q:"What was one thing scarce in Norwood during World War II because of the national emergency?",a:["Gasoline","Electricity","Tap water","Newspapers"],c:0,cat:"History",fact:"Historical accounts describe automobiles and gasoline as scarce, while food was rationed.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"What did Norwood households use for food purchases during World War II?",a:["Ration books","Cryptocurrency","Company scrip","Rail passes"],c:0,cat:"History",fact:"The Historical Society recounts local households shopping with ration books during World War II.",src:"https://norwoodhistoricalsociety.org/roaring-twenties-depression-and-world-war-ii/"},
{q:"Which civic landmark overlooks the modern Town Common?",a:["Memorial Municipal Building","Norwood Airport terminal","Plimpton Press","Bendix plant"],c:0,cat:"Architecture",fact:"Norwood's Memorial Municipal Building/Town Hall is a defining architectural presence at the Town Common.",src:"https://norwoodhistoricalsociety.org/the-town-square/"},
{q:"In 1879, which famous showman’s tiny-statured performers appeared at Norwood’s Village Hall?",a:["Buffalo Bill Cody","P. T. Barnum","Harry Houdini","Florenz Ziegfeld"],c:1,cat:"Local Oddities",fact:"Major Tom Thumb and his troupe, famous through P. T. Barnum, performed at Village Hall in October 1879.",src:"https://norwoodhistoricalsociety.org/major-tom-thumb-and-famed-troupe-once-graced-stage-of-village-hall-this-day-in-norwood-history-december-21-1946/"},
{q:"What cutting-edge invention was demonstrated at Norwood’s old Village Hall in the early 1890s?",a:["A television","A microwave oven","An Edison talking machine","A helicopter"],c:2,cat:"Local Oddities",fact:"A historical account recalls a first-model Edison 'talking machine' being demonstrated at a Universalist church fair in Village Hall.",src:"https://norwoodhistoricalsociety.org/major-tom-thumb-and-famed-troupe-once-graced-stage-of-village-hall-this-day-in-norwood-history-december-21-1946/"},
{q:"A 1953 air show at Norwood Airport was expected to draw about how many people?",a:["500","2,000","10,000","50,000"],c:2,cat:"Airport",fact:"Organizers prepared for more than 10,000 visitors during Norwood Airport Week’s free all-day air show.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-june-19-1953-expect-10000-in-norwood-for-big-air-show-sunday/"},
{q:"What military aircraft was advertised as a star attraction at Norwood Airport’s 1953 air show?",a:["A 600-mph Thunderjet fighter","A B-2 stealth bomber","The Spirit of St. Louis","A Concorde"],c:0,cat:"Airport",fact:"The Air Force planned to display a Thunderjet fighter, advertised at the time as capable of 600 mph, at the Norwood Airport show.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-june-19-1953-expect-10000-in-norwood-for-big-air-show-sunday/"},
{q:"Norwood resident H. Roy Waite took part in an early aviation bombing test by dropping what from a Wright biplane?",a:["Water balloons","Flour-filled bags","Wooden blocks","Bundles of newspapers"],c:1,cat:"Local Oddities",fact:"In a 1912 test over Boston Harbor, Waite served as bombardier and dropped flour-filled bags at military targets.",src:"https://norwoodhistoricalsociety.org/norwood-aviator-conducts-americas-first-bombing-tests-this-day-in-norwood-history-june-11-1964/"},
{q:"What unusual feature did diplomat W. Cameron Forbes reportedly have on the lawn of his Norwood home?",a:["A miniature railroad","A polo field","A lighthouse","An airplane runway"],c:1,cat:"People",fact:"A 1931 account described Forbes as an avid polo player with a polo field on his front lawn in Norwood.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-august-11/"},
{q:"In 1902, a group of Norwood youths got into serious trouble after doing what as a pre-Fourth-of-July prank?",a:["Greasing streetcar rails","Painting the Town Hall","Releasing farm animals","Stealing a locomotive bell"],c:0,cat:"Local Oddities",fact:"Eight young men were indicted after greased streetcar rails contributed to a serious accident on the Old Colony Street Railway.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-september-10-1902/"},
{q:"When Norwood’s Junior High School burned in 1971, what made the fire especially hazardous?",a:["A train derailment","An underground gas well","Exploding science-lab chemicals","A nearby fireworks factory"],c:2,cat:"History",fact:"The 1971 general-alarm fire included an explosion involving chemical supplies in a science laboratory; no injuries were reported.",src:"https://norwoodhistoricalsociety.org/this-day-in-norwood-history-january-23/"},
{q:"Which neighboring town’s path to independence was influenced in part by Dedham giving Norwood the water rights to Buckmaster Pond?",a:["Westwood","Walpole","Canton","Needham"],c:0,cat:"Local Oddities",fact:"Buckmaster Pond was in West Dedham when Dedham transferred its water rights to Norwood in 1885. Westwood’s official history identifies resentment over the loss of those rights as one factor in West Dedham’s later separation from Dedham; Westwood incorporated in 1897.",src:"https://www.townhall.westwood.ma.us/our-town/about-westwood/town-history"},
{q:"Which lead singer of The Mighty Mighty Bosstones graduated from Norwood High School?",a:["Dicky Barrett","Dave Grohl","Eddie Vedder","Rivers Cuomo"],c:0,cat:"Notable Alumni",fact:"Dicky Barrett, longtime frontman of Boston ska-punk band The Mighty Mighty Bosstones, grew up in Norwood and graduated from Norwood High School.",src:"https://www.bostonmagazine.com/arts-entertainment/2016/12/18/bosstones-joe-keohane/"},
{q:"Which phrase best describes the intended character of this trivia bank?",a:["Sourced local facts rather than folklore presented as fact","Unsourced rumors","Only train questions","Only current politics"],c:0,cat:"Meta",fact:"Norwood.ma's trivia bank stores a source with each question so interesting local claims can be checked.",src:"https://norwoodlibrary.org/digital-archive/"}
];
